Method.Implementation:
set tSC = $$$OK
Set RootFile = ##class(%ResultSet).%New("%File:FileSet")
Set tSC = RootFile.%Execute(..SrcDirectory, ..SearchPattern, "Name", 0)
Set n = 0
While RootFile.Next()
{
	set DataFile =  RootFile.Get("ItemName") 
	if (RootFile.Get("Type") = "F")
	{
		Try {
			 $$$TRACE( DataFile _ ", size: " _ ##class(%File).GetFileSize(..SrcDirectory _ DataFile))
			 #dim tRequestObj As EnsLib.HL7.Message

			 Set tRequestObj = ##class(EnsLib.HL7.Message).ImportFromFile(..SrcDirectory _ DataFile)

			 set tSC = tRequestObj.DocTypeSet(..DocType)
			 $$$TRACE( "Create Hl7 message: size: " _ tRequestObj.FullSize _ ", stat: " _ tSC)

			 set tSC =  ##Class(EnsLib.Testing.Service).SendTestRequest(..TargetComp, tRequestObj, .tResponse, .tSessionId)

			 $$$TRACE( "Call SendTestRequest to "_ ..TargetComp _ ", stat: " _ tSC _ ", tResponse " _ tResponse _ ", tSessionId " _ tSessionId)

		}
		Catch (ex) {
			Set tSC = ex.AsStatus()
		}
		If $$$ISERR(tSC) {
			$$$LOGERROR( $system.Status.GetErrorText(tSC))

		}
	}

}
return tSC
